WHERE order_id = 1042 AND device LIKE 'phone-%'
ORDER BY ts;

schema:
CREATE TABLE couriers (id TEXT PRIMARY KEY, name TEXT NOT NULL, vehicle TEXT NOT NULL);
CREATE TABLE orders (id INTEGER PRIMARY KEY, courier_id TEXT REFERENCES couriers(id), restaurant TEXT,
                     created_at TEXT, delivered_at TEXT, minutes INTEGER);
CREATE TABLE reviews (order_id INTEGER REFERENCES orders(id), stars INTEGER CHECK (stars BETWEEN 1 AND 5), text TEXT);
CREATE TABLE stops (courier_id TEXT REFERENCES couriers(id), ts TEXT, place TEXT, minutes INTEGER);

questions.a:
SELECT id, courier_id, minutes FROM orders
WHERE id IN (3006, 3013, 3020)
ORDER BY id;

SELECT courier_id, ts, place, minutes FROM stops
WHERE minutes > 10
ORDER BY minutes DESC;

SELECT ts, place, minutes FROM stops
WHERE courier_id = 'c2' AND place LIKE '%Парк%'
ORDER BY ts;

SELECT name FROM couriers
WHERE id IN (SELECT courier_id FROM orders
             WHERE id IN (SELECT order_id FROM reviews WHERE text LIKE '%шматк%'));

