                      customer_id TEXT REFERENCES customers(id), stars INTEGER CHECK (stars BETWEEN 1 AND 5), ts TEXT);

CREATE TABLE couriers (id TEXT PRIMARY KEY, name TEXT NOT NULL, vehicle TEXT NOT NULL);
CREATE TABLE gps (courier_id TEXT, t_min INTEGER, ts TEXT, x_km REAL, y_km REAL);   -- t_min: хвилина від 09:00
CREATE TABLE deliveries (order_id INTEGER, courier_id TEXT, t_min INTEGER);

questions.a:
SELECT ts, gap FROM (
  SELECT ts, t_min, t_min - LAG(t_min) OVER (ORDER BY t_min) AS gap
  FROM pings WHERE courier_id = 'c1'
) WHERE gap > 5
ORDER BY t_min;

SELECT courier_id, SUM(CASE WHEN gap >= 30 THEN 1 ELSE 0 END) AS breaks
FROM (
  SELECT courier_id, t_min - LAG(t_min) OVER (PARTITION BY courier_id ORDER BY t_min) AS gap
  FROM pings
)
GROUP BY courier_id;
